package com.milano.quotation.logistics;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ArrayNode;
import tools.jackson.databind.node.ObjectNode;
import com.milano.quotation.common.AppException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Instant;import java.util.*;

@Service
public class LogisticsService{
    private final LogisticsProviderRepository providers;private final LogisticsChannelRepository channels;private final LogisticsVersionRepository versions;private final LogisticsWorkbookService workbooks;private final LogisticsDatasetGuard datasetGuard;
    public LogisticsService(LogisticsProviderRepository providers,LogisticsChannelRepository channels,LogisticsVersionRepository versions,LogisticsWorkbookService workbooks,LogisticsDatasetGuard datasetGuard){this.datasetGuard=datasetGuard;this.providers=providers;this.channels=channels;this.versions=versions;this.workbooks=workbooks;}
    @Transactional(readOnly=true) public long publishedChannelCount(){return channels.countByCurrentVersionIdIsNotNullAndArchivedAtIsNull();}
    @Transactional(readOnly=true) public ArrayNode publishedRows(UUID channelId){var channel=channels.findById(channelId).orElseThrow(()->AppException.notFound("物流渠道不存在"));if(channel.currentVersionId==null)return tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode();var version=versions.findById(channel.currentVersionId).orElseThrow(()->AppException.notFound("物流正式版本不存在"));var rows=version.payload.path("rows");return rows.isArray()?(ArrayNode)rows.deepCopy():tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode();}
    @Transactional(readOnly=true) public Workspace workspace(){return new Workspace(providers.findAllByOrderByUpdatedAtDesc().stream().map(this::providerView).toList(),channels.findAllByOrderByUpdatedAtDesc().stream().map(this::channelView).toList(),versions.findAllByOrderByCreatedAtDesc().stream().map(this::versionView).toList());}
    @Transactional public JsonNode addProvider(ObjectNode body){datasetGuard.writable(datasetGuard.activeId());var name=required(body,"name",120);var code=required(body,"code",64).toUpperCase(Locale.ROOT);if(providers.existsByCodeIgnoreCase(code))throw AppException.conflict("物流商编码已存在");var now=Instant.now();var row=new LogisticsProviderEntity();row.id=UUID.randomUUID();row.code=code;var payload=body.deepCopy();payload.put("id",row.id.toString());payload.put("name",name);payload.put("code",code);payload.put("enabled",body.path("enabled").asBoolean(true));payload.put("createdAt",now.toString());payload.put("updatedAt",now.toString());row.payload=payload;row.createdAt=now;row.updatedAt=now;providers.save(row);return providerView(row);}
    @Transactional public JsonNode setProviderEnabled(UUID id,boolean enabled,long expectedVersion){var row=providers.findById(id).orElseThrow(()->AppException.notFound("物流商不存在"));if(row.version!=expectedVersion)throw AppException.conflict("物流商已被其他用户修改，请刷新后重试");((ObjectNode)row.payload).put("enabled",enabled).put("updatedAt",Instant.now().toString());row.updatedAt=Instant.now();providers.saveAndFlush(row);return providerView(row);}
    @Transactional public void deleteProvider(UUID id){var row=providers.findById(id).orElseThrow(()->AppException.notFound("物流商不存在"));if(channels.countByProviderId(id)>0)throw AppException.conflict("物流商已有渠道，只能停用，不能删除");providers.delete(row);}
    @Transactional public JsonNode addChannel(ObjectNode body){var providerId=uuid(body.path("providerId").asText(),"物流商不存在");datasetGuard.activeProvider(providerId);if(!providers.existsById(providerId))throw AppException.notFound("物流商不存在");var name=required(body,"name",120);var code=required(body,"code",96).toUpperCase(Locale.ROOT);if(channels.existsByCodeIgnoreCase(code))throw AppException.conflict("渠道编码已存在");var now=Instant.now();var row=new LogisticsChannelEntity();row.id=UUID.randomUUID();row.providerId=providerId;row.code=code;row.ruleId=datasetGuard.nextRuleId();var payload=body.deepCopy();payload.put("id",row.id.toString());payload.put("ruleId",row.ruleId);payload.put("providerId",providerId.toString());payload.put("name",name);payload.put("code",code);payload.put("enabled",body.path("enabled").asBoolean(true));payload.put("currentVersionId","");payload.put("createdAt",now.toString());payload.put("updatedAt",now.toString());row.payload=payload;row.createdAt=now;row.updatedAt=now;channels.save(row);return channelView(row);}
    @Transactional public JsonNode updateChannel(UUID id,ObjectNode body,long expectedVersion){var row=channels.findById(id).orElseThrow(()->AppException.notFound("物流渠道不存在"));if(row.version!=expectedVersion)throw AppException.conflict("物流渠道已被其他用户修改，请刷新后重试");var code=required(body,"code",96).toUpperCase(Locale.ROOT);if(!row.code.equalsIgnoreCase(code)&&channels.existsByCodeIgnoreCase(code))throw AppException.conflict("渠道编码已存在");var payload=(ObjectNode)row.payload;payload.put("name",required(body,"name",120));payload.put("code",code);payload.put("type",body.path("type").asText("专线"));payload.put("logisticsAttribute",body.path("logisticsAttribute").asText("普货"));payload.put("enabled",body.path("enabled").asBoolean(payload.path("enabled").asBoolean(true)));payload.put("updatedAt",Instant.now().toString());row.code=code;row.updatedAt=Instant.now();channels.saveAndFlush(row);return channelView(row);}
    @Transactional public JsonNode setChannelEnabled(UUID id,boolean enabled,long expectedVersion){var row=channels.findById(id).orElseThrow(()->AppException.notFound("物流渠道不存在"));if(row.version!=expectedVersion)throw AppException.conflict("物流渠道已被其他用户修改，请刷新后重试");((ObjectNode)row.payload).put("enabled",enabled).put("updatedAt",Instant.now().toString());row.updatedAt=Instant.now();channels.saveAndFlush(row);return channelView(row);}
    @Transactional public JsonNode cloneChannel(UUID id,ObjectNode body){var source=channels.findById(id).orElseThrow(()->AppException.notFound("物流渠道不存在"));var input=(ObjectNode)source.payload.deepCopy();input.put("name",body.path("name").asText(input.path("name").asText()+"-副本"));input.put("code",required(body,"code",96));input.put("providerId",source.providerId.toString());input.put("currentVersionId","");var clone=addChannel(input);if(source.currentVersionId!=null){var published=versions.findById(source.currentVersionId).orElseThrow(()->AppException.notFound("物流正式版本不存在"));var draftBody=(ObjectNode)published.payload.deepCopy();draftBody.put("sourceHash","clone:"+source.id+":"+UUID.randomUUID());draftBody.put("fileName","克隆自"+published.payload.path("fileName").asText("正式版本"));draftBody.put("auditNote","克隆渠道产生的待审草稿");createDraft(UUID.fromString(clone.path("id").asText()),draftBody);}return clone;}
    @Transactional public void deleteChannel(UUID id){var row=channels.findById(id).orElseThrow(()->AppException.notFound("物流渠道不存在"));if(!versions.findByChannelIdOrderByVersionNumberDesc(id).isEmpty())throw AppException.conflict("渠道已有版本记录，只能停用，不能删除");channels.delete(row);}
    @Transactional public ObjectNode archiveChannel(UUID id,String reason,String actor,long expectedVersion){
        var row=channels.findById(id).orElseThrow(()->AppException.notFound("物流渠道不存在"));
        if(row.version!=expectedVersion)throw AppException.conflict("物流渠道已被其他用户修改，请刷新后重试");
        if(row.archivedAt!=null)throw AppException.conflict("物流渠道已经归档");
        if(reason==null||reason.trim().isEmpty()||reason.trim().length()>500)throw AppException.unprocessable("归档原因不能为空或过长");
        var now=Instant.now();var rejectedIds=tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode();
        for(var version:versions.findByChannelIdOrderByVersionNumberDesc(id))if("draft".equals(version.status)){reject(version,"渠道归档自动终止："+reason.trim(),actor);rejectedIds.add(version.id.toString());}
        row.archivedAt=now;row.archivedBy=actor;row.archiveReason=reason.trim();row.updatedAt=now;
        ((ObjectNode)row.payload).put("archived",true).put("archivedAt",now.toString()).put("archivedBy",actor).put("archiveReason",reason.trim()).put("updatedAt",now.toString());
        channels.saveAndFlush(row);var result=(ObjectNode)channelView(row);result.put("rejectedDrafts",rejectedIds.size()).set("rejectedVersionIds",rejectedIds);return result;
    }
    @Transactional public JsonNode createManualDraft(UUID channelId,ObjectNode body){var rows=body.path("rows");if(!rows.isArray())throw AppException.unprocessable("区域规则必须是数组");for(var row:rows){var from=row.path("weightFromKg").asDouble(-1);var to=row.path("weightToKg").asDouble(-1);if(from<0||to<from)throw AppException.unprocessable("区域计费重量范围非法");if(row.path("areaName").asText("").isBlank())throw AppException.unprocessable("区域名称不能为空");}versions.findByChannelIdOrderByVersionNumberDesc(channelId).stream().filter(version->"draft".equals(version.status)).forEach(version->{version.status="rejected";((ObjectNode)version.payload).put("status","rejected").put("auditNote","被后续手工编辑草稿替代");});var payload=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode();payload.put("sourceHash","manual:"+channelId+":"+UUID.randomUUID());payload.put("fileName",body.path("fileName").asText("手工维护区域规则"));payload.set("rows",rows.deepCopy());payload.set("issues",tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode());payload.set("diffRows",tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode());payload.set("summary",tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("added",rows.size()).put("price",0).put("rule",0).put("removed",0).put("unchanged",0).put("highRisk",0));payload.put("validRows",rows.size()).put("errors",0).put("warnings",0).put("importedBy",body.path("actor").asText("物流负责人")).put("publishedBy","").put("auditNote",body.path("note").asText("手工维护产生的待审草稿"));return createDraft(channelId,payload);}
    @Transactional public JsonNode createDraft(UUID channelId,ObjectNode body){return createDraftInternal(channelId,body,false,"被后续导入草稿终止");}
    @Transactional public JsonNode createDraftReplacing(UUID channelId,ObjectNode body,String reason){return createDraftInternal(channelId,body,true,reason);}
    private JsonNode createDraftInternal(UUID channelId,ObjectNode body,boolean replaceDrafts,String reason){
        datasetGuard.channel(channelId);
        var channel=channels.findById(channelId).orElseThrow(()->AppException.notFound("物流渠道不存在"));
        var base=channel.currentVersionId==null?"":channel.currentVersionId.toString();
        if(!body.hasNonNull("parserVersion")&&versions.findByChannelIdOrderByVersionNumberDesc(channelId).stream().anyMatch(v->v.payload.hasNonNull("parserVersion")))
            throw AppException.unprocessable("该渠道由原表导入管理，请使用新版导入与更新，不能通过旧手工入口移除待适配条件");
        var contentHash=body.path("contentHash").asText(required(body,"sourceHash",128));
        var sourceHash=LogisticsDatasetService.hash(contentHash+":"+base);
        var duplicate=versions.findByChannelIdAndSourceHash(channelId,sourceHash);
        if(duplicate.isPresent() && ("draft".equals(duplicate.get().status) || duplicate.get().id.equals(channel.currentVersionId))) return versionView(duplicate.get());
        if(duplicate.isPresent()) sourceHash=sourceHash+":"+UUID.randomUUID();
        var activeDrafts=versions.findByChannelIdOrderByVersionNumberDesc(channelId).stream().filter(v->"draft".equals(v.status)).toList();
        if(!activeDrafts.isEmpty()&&!replaceDrafts)throw AppException.conflict("渠道已有不同的待审核版本，请先终止旧草稿或明确替换");
        if(replaceDrafts)activeDrafts.forEach(version->reject(version,reason,body.path("importedBy").asText("物流负责人")));
        var now=Instant.now();var row=new LogisticsVersionEntity();row.id=UUID.randomUUID();row.channelId=channelId;
        row.versionNumber=versions.findByChannelIdOrderByVersionNumberDesc(channelId).stream().mapToInt(v->v.versionNumber).max().orElse(0)+1;
        row.status="draft";row.sourceHash=sourceHash;var payload=body.deepCopy();
        payload.put("id",row.id.toString()).put("channelId",channelId.toString()).put("versionNumber",row.versionNumber)
            .put("status","draft").put("importedAt",now.toString()).put("publishedAt","").put("sourceHash",sourceHash)
            .put("contentHash",contentHash).put("basePublishedVersionId",base);
        var comparison=workbooks.compare((ArrayNode)payload.path("rows"),publishedRows(channelId));
        payload.set("summary",comparison.path("summary"));payload.set("diffRows",comparison.path("diffRows"));
        row.payload=payload;row.createdAt=now;versions.save(row);return versionView(row);
    }
    @Transactional public JsonNode recompare(UUID channelId,UUID versionId){
        datasetGuard.channel(channelId);
        var channel=channels.findById(channelId).orElseThrow(()->AppException.notFound("物流渠道不存在"));
        var version=versions.findById(versionId).orElseThrow(()->AppException.notFound("物流版本不存在"));
        if(!version.channelId.equals(channelId)||!"draft".equals(version.status))throw AppException.conflict("只有当前渠道待审稿可以重新对比");
        var payload=(ObjectNode)version.payload;
        var comparison=workbooks.compare((ArrayNode)payload.path("rows"),publishedRows(channelId));
        payload.set("summary",comparison.path("summary"));payload.set("diffRows",comparison.path("diffRows"));
        payload.put("basePublishedVersionId",channel.currentVersionId==null?"":channel.currentVersionId.toString());
        return versionView(version);
    }
    @Transactional public JsonNode publish(UUID channelId,UUID versionId,String note,String actor,boolean removalConfirmed){return publishReviewed(channelId,versionId,note,actor,removalConfirmed,false);}
    @Transactional public JsonNode publishReviewed(UUID channelId,UUID versionId,String note,String actor,boolean removalConfirmed,boolean reviewConfirmed){return versionView(publishReviewedEntity(channelId,versionId,note,actor,removalConfirmed,reviewConfirmed));}
    private LogisticsVersionEntity publishReviewedEntity(UUID channelId,UUID versionId,String note,String actor,boolean removalConfirmed,boolean reviewConfirmed){datasetGuard.channel(channelId);var channel=channels.findById(channelId).orElseThrow(()->AppException.notFound("物流渠道不存在"));var target=versions.findById(versionId).orElseThrow(()->AppException.notFound("物流版本不存在"));validateBaseline(channel,target);if(target.payload.path("summary").path("highRisk").asInt()>0&&!reviewConfirmed)throw AppException.unprocessable("大幅涨跌必须明确确认风险");if(!target.channelId.equals(channelId))throw AppException.conflict("版本不属于该渠道");if(!"draft".equals(target.status))throw AppException.conflict("只有待审核草稿可以发布");if(note==null||note.isBlank())throw AppException.unprocessable("发布审核备注不能为空");if(target.payload.path("errors").asInt()>0)throw AppException.unprocessable("当前版本存在阻断错误，禁止发布");if(hasCoverageRemoval(target.payload)&&!removalConfirmed)throw AppException.unprocessable("存在移除或重量覆盖缩小项时必须明确确认");var now=Instant.now();versions.findByChannelIdOrderByVersionNumberDesc(channelId).stream().filter(v->v.status.equals("published")).forEach(v->{v.status="superseded";((ObjectNode)v.payload).put("status","superseded");});target.status="published";target.publishedAt=now;var payload=(ObjectNode)target.payload;payload.put("status","published");payload.put("publishedAt",now.toString());payload.put("publishedBy",actor);payload.put("auditNote",note.trim());channel.currentVersionId=target.id;channel.updatedAt=now;var channelPayload=(ObjectNode)channel.payload;channelPayload.put("currentVersionId",target.id.toString());channelPayload.put("updatedAt",now.toString());return target;}
    @Transactional public JsonNode rollback(UUID channelId,UUID targetId,String note,String actor){var target=versions.findById(targetId).orElseThrow(()->AppException.notFound("目标版本不存在"));if(!target.channelId.equals(channelId))throw AppException.conflict("版本不属于该渠道");if(!Set.of("published","superseded").contains(target.status))throw AppException.conflict("只能回滚到曾经生效的版本");var body=(ObjectNode)target.payload.deepCopy();body.put("sourceHash","rollback:"+target.id+":"+System.nanoTime());body.put("fileName","回滚自V"+target.versionNumber+" · "+body.path("fileName").asText("历史版本"));body.put("rollbackFromVersionId",target.id.toString());body.put("importedBy",actor);var draft=(ObjectNode)createDraftReplacing(channelId,body,"回滚操作终止旧草稿");var id=UUID.fromString(draft.path("id").asText());return publishReviewed(channelId,id,note==null||note.isBlank()?"回滚至V"+target.versionNumber:note,actor,true,true);}
    @Transactional public JsonNode rejectDraft(UUID channelId,UUID versionId,String note,String actor){datasetGuard.channel(channelId);var target=versions.findById(versionId).orElseThrow(()->AppException.notFound("物流版本不存在"));if(!target.channelId.equals(channelId))throw AppException.conflict("版本不属于该渠道");if(!"draft".equals(target.status))throw AppException.conflict("只有待审核草稿可以终止");if(note==null||note.isBlank())throw AppException.unprocessable("终止原因不能为空");reject(target,note.trim(),actor);return versionView(target);}
    private void reject(LogisticsVersionEntity version,String note,String actor){version.status="rejected";var payload=(ObjectNode)version.payload;payload.put("status","rejected").put("rejectedAt",Instant.now().toString()).put("rejectedBy",actor).put("auditNote",note);}

    @Transactional(readOnly=true) public ObjectNode matchProviderFile(UUID providerId,String fileName,String sourceHash){
        var provider=providers.findById(providerId).orElseThrow(()->AppException.notFound("物流商不存在"));var stem=stripFileSuffix(fileName);var normalized=normalize(stem);var matches=new LinkedHashSet<LogisticsChannelEntity>();
        for(var channel:channels.findByProviderIdOrderByUpdatedAtDesc(providerId)){
            if(codeMatches(stem,channel.code)||normalize(channel.payload.path("name").asText()).equals(normalized))matches.add(channel);
            for(var alias:channel.payload.path("aliases"))if(normalize(alias.asText()).equals(normalized))matches.add(channel);
        }
        if(matches.size()>1)throw AppException.conflict("文件名匹配到多个渠道，请在文件名中保留唯一渠道编码："+fileName);
        if(matches.isEmpty())for(var channel:channels.findAllByOrderByUpdatedAtDesc())if(!channel.providerId.equals(providerId)&&codeMatches(stem,channel.code))throw AppException.conflict("文件中的渠道编码属于其他物流商："+channel.code);
        var result=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("fileName",fileName).put("sourceHash",sourceHash);
        if(!matches.isEmpty()){var channel=matches.iterator().next();result.put("action",channel.archivedAt==null?"match":"restore").put("matchType",codeMatches(stem,channel.code)?"code":"name").put("channelId",channel.id.toString()).put("channelName",channel.payload.path("name").asText()).put("channelCode",channel.code).put("archived",channel.archivedAt!=null).put("hasDraft",versions.findByChannelIdOrderByVersionNumberDesc(channel.id).stream().anyMatch(v->"draft".equals(v.status)));}
        else{var providerCode=provider.code.replaceAll("[^A-Z0-9]","");var suffix=(sourceHash==null||sourceHash.length()<12?UUID.randomUUID().toString().replace("-",""):sourceHash).substring(0,12).toUpperCase(Locale.ROOT);result.put("action","create").put("matchType","new").put("channelId","").put("channelName",stem).put("channelCode","AUTO-"+providerCode+"-"+suffix);}
        return result;
    }
    @Transactional(readOnly=true) public ObjectNode matchGlobalProvider(String fileName){
        var prefix=providerMatchPrefix(stripFileSuffix(fileName));var matched=new ArrayList<LogisticsProviderEntity>();
        for(var provider:providers.findAllByOrderByUpdatedAtDesc())if(prefix.length()==2&&prefix.equals(providerMatchPrefix(provider.payload.path("name").asText())))matched.add(provider);
        var result=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("providerPrefix",prefix);
        if(matched.isEmpty())return result.put("providerMatchStatus","unmatched").put("providerMatchMessage","文件名前两个有效字符未匹配物流商");
        if(matched.size()>1)return result.put("providerMatchStatus","ambiguous").put("providerMatchMessage","文件名前两个有效字符匹配到多个物流商");
        var provider=matched.get(0);if(!provider.payload.path("enabled").asBoolean(true))return result.put("providerMatchStatus","disabled").put("providerId",provider.id.toString()).put("providerName",provider.payload.path("name").asText()).put("providerMatchMessage","匹配物流商已停用");
        return result.put("providerMatchStatus","matched").put("providerId",provider.id.toString()).put("providerName",provider.payload.path("name").asText()).put("providerCode",provider.code);
    }
    @Transactional public ObjectNode importProviderBatch(UUID providerId,ArrayNode items,String actor,boolean replaceDrafts){
        if(!providers.existsById(providerId))throw AppException.notFound("物流商不存在");if(items.isEmpty())throw AppException.unprocessable("请选择至少一个物流模板");var claimed=new HashSet<String>();
        for(var item:items){if(item.path("errors").asInt()>0)throw AppException.unprocessable("文件存在阻断错误："+item.path("fileName").asText());var claim=item.path("channelId").asText();if(claim.isBlank())claim=item.path("channelCode").asText();if(!claimed.add(claim))throw AppException.conflict("同一批次中一个渠道只能对应一个文件："+item.path("fileName").asText());if(!item.path("channelId").asText().isBlank()){var channel=channels.findById(UUID.fromString(item.path("channelId").asText())).orElseThrow(()->AppException.notFound("匹配渠道不存在"));if(!channel.providerId.equals(providerId))throw AppException.conflict("匹配渠道不属于当前物流商");var duplicate=versions.findByChannelIdAndSourceHash(channel.id,item.path("sourceHash").asText());if(duplicate.isEmpty()&&!replaceDrafts&&versions.findByChannelIdOrderByVersionNumberDesc(channel.id).stream().anyMatch(v->"draft".equals(v.status)))throw AppException.conflict("渠道已有不同待审稿："+channel.payload.path("name").asText());}}
        var output=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode();var results=output.putArray("items");
        for(var item:items){LogisticsChannelEntity channel;var created=false;if(item.path("channelId").asText().isBlank()){var input=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("providerId",providerId.toString()).put("name",required((ObjectNode)item,"channelName",120)).put("code",required((ObjectNode)item,"channelCode",96)).put("type","专线").put("logisticsAttribute","普货").put("enabled",true);var view=addChannel(input);channel=channels.findById(UUID.fromString(view.path("id").asText())).orElseThrow();created=true;}else channel=channels.findById(UUID.fromString(item.path("channelId").asText())).orElseThrow();var restored=restore(channel,actor);var body=(ObjectNode)item.deepCopy();body.put("importedBy",actor).put("publishedBy","").put("auditNote","批量导入产生的待审核草稿");var existing=versions.findByChannelIdAndSourceHash(channel.id,item.path("sourceHash").asText());JsonNode version;if(restored&&existing.isPresent()&&channel.currentVersionId!=null)version=versions.findById(channel.currentVersionId).map(this::versionView).orElseThrow();else if(restored&&existing.isPresent()){body.put("sourceHash","restore:"+existing.get().id+":"+UUID.randomUUID());body.put("contentHash",item.path("sourceHash").asText());version=createDraftInternal(channel.id,body,replaceDrafts,"被物流商批量导入的新草稿终止");}else version=createDraftInternal(channel.id,body,replaceDrafts,"被物流商批量导入的新草稿终止");results.addObject().put("fileName",item.path("fileName").asText()).put("channelId",channel.id.toString()).put("channelName",channel.payload.path("name").asText()).put("versionId",version.path("id").asText()).put("versionNumber",version.path("versionNumber").asInt()).put("action",restored?(existing.isPresent()&&channel.currentVersionId!=null?"restored":"restored-draft"):existing.isPresent()?"duplicate":created?"created":"updated");}
        output.put("providerId",providerId.toString()).put("count",results.size());return output;
    }
    @Transactional public ObjectNode importGlobalBatch(ArrayNode items,String actor,boolean replaceDrafts){
        if(items.isEmpty())throw AppException.unprocessable("请选择至少一个物流模板");var grouped=new LinkedHashMap<UUID,ArrayNode>();
        for(var item:items){var providerId=uuid(item.path("providerId").asText(),"文件未匹配物流商");grouped.computeIfAbsent(providerId,ignored->tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode()).add(item);}
        var output=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode();var results=output.putArray("items");
        for(var entry:grouped.entrySet()){var part=importProviderBatch(entry.getKey(),entry.getValue(),actor,replaceDrafts);part.path("items").forEach(results::add);}
        output.put("count",results.size()).put("providerCount",grouped.size());return output;
    }
    @Transactional public ObjectNode publishProviderBatch(UUID providerId,ArrayNode selections,String note,String actor){
        if(note==null||note.isBlank())throw AppException.unprocessable("批量审核备注不能为空");if(selections.isEmpty())throw AppException.unprocessable("请选择至少一个待审核版本");var pairs=new ArrayList<Map.Entry<LogisticsChannelEntity,LogisticsVersionEntity>>();
        for(var selection:selections){var channel=channels.findById(uuid(selection.path("channelId").asText(),"渠道不存在")).orElseThrow(()->AppException.notFound("渠道不存在"));if(!channel.providerId.equals(providerId))throw AppException.conflict("所选渠道不属于当前物流商");var version=versions.findById(uuid(selection.path("versionId").asText(),"版本不存在")).orElseThrow(()->AppException.notFound("版本不存在"));validatePublish(channel,version,selection.path("removalConfirmed").asBoolean(false));if(version.payload.path("summary").path("highRisk").asInt()>0&&!selection.path("reviewConfirmed").asBoolean(false))throw AppException.unprocessable("大幅涨跌版本必须完成风险核对："+channel.payload.path("name").asText());pairs.add(Map.entry(channel,version));}
        // Keep the atomic transaction, but never accumulate every published
        // version's full rows/diff payload in the HTTP/idempotency response.
        // A seven-channel supplier workbook can otherwise exceed 100 MB and
        // exhaust a 1 GiB backend before the transaction commits.
        var result=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode();var published=result.putArray("published");
        for(int i=0;i<pairs.size();i++){
            var pair=pairs.get(i);var selection=selections.get(i);
            publishReviewedEntity(pair.getKey().id,pair.getValue().id,note,actor,selection.path("removalConfirmed").asBoolean(false),selection.path("reviewConfirmed").asBoolean(false));
            published.addObject().put("id",pair.getValue().id.toString()).put("channelId",pair.getKey().id.toString())
                    .put("versionNumber",pair.getValue().versionNumber).put("status",pair.getValue().status)
                    .put("quoteReady",datasetGuard.quoteReady(pair.getValue().id));
        }
        result.put("providerId",providerId.toString()).put("count",published.size());return result;
    }
    private void validatePublish(LogisticsChannelEntity channel,LogisticsVersionEntity target,boolean removalConfirmed){datasetGuard.channel(channel.id);validateBaseline(channel,target);if(!target.channelId.equals(channel.id))throw AppException.conflict("版本不属于该渠道");if(!"draft".equals(target.status))throw AppException.conflict("只有待审核草稿可以发布");if(target.payload.path("errors").asInt()>0)throw AppException.unprocessable("当前版本存在阻断错误，禁止发布");if(hasCoverageRemoval(target.payload)&&!removalConfirmed)throw AppException.unprocessable("存在移除或重量覆盖缩小项时必须明确确认");}
    private static boolean hasCoverageRemoval(JsonNode payload){var summary=payload.path("summary");return summary.path("removed").asInt()>0||summary.path("coverageReduced").asInt()>0;}
    private void validateBaseline(LogisticsChannelEntity channel,LogisticsVersionEntity target){
        var current=channel.currentVersionId==null?"":channel.currentVersionId.toString();
        if(!target.payload.has("basePublishedVersionId") || !target.payload.path("basePublishedVersionId").asText().equals(current))
            throw AppException.conflict("正式价格已变化或旧稿缺少基线，请重新对比并审核");
        if(!target.payload.path("rows").isArray() || target.payload.path("rows").isEmpty())
            throw AppException.unprocessable("没有可发布价格");
    }
    private void repairDraftComparisons(){var channelIndex=new HashMap<UUID,LogisticsChannelEntity>();channels.findAllByOrderByUpdatedAtDesc().forEach(channel->channelIndex.put(channel.id,channel));for(var version:versions.findAllByOrderByCreatedAtDesc()){if(!"draft".equals(version.status)||!version.payload.path("rows").isArray())continue;var channel=channelIndex.get(version.channelId);var previous=tools.jackson.databind.node.JsonNodeFactory.instance.arrayNode();if(channel!=null&&channel.currentVersionId!=null){var published=versions.findById(channel.currentVersionId).orElse(null);if(published!=null&&"published".equals(published.status)&&published.payload.path("rows").isArray())previous=(ArrayNode)published.payload.path("rows");}var comparison=workbooks.compare((ArrayNode)version.payload.path("rows"),previous);var payload=(ObjectNode)version.payload;payload.set("diffRows",comparison.path("diffRows"));payload.set("summary",comparison.path("summary"));}}
    private static String stripFileSuffix(String value){var stem=value==null?"":value.replaceFirst("(?i)\\.xlsx$","").trim();return stem.replaceFirst("(?i)[-_ ]*(价格变动测试|价格更新|更新价格|V\\d+)$","").trim();}
    private static String normalize(String value){return value==null?"":value.toLowerCase(Locale.ROOT).replaceAll("[\\s_\\-—–·()（）]","");}
    static String providerMatchPrefix(String value){var normalized=normalize(value).replaceAll("[\\p{P}\\p{S}]","").toUpperCase(Locale.ROOT);return normalized.codePoints().limit(2).collect(StringBuilder::new,StringBuilder::appendCodePoint,StringBuilder::append).toString();}
    private static boolean codeMatches(String stem,String code){if(stem==null||code==null||code.isBlank())return false;return java.util.regex.Pattern.compile("(?i)(?<![A-Z0-9])"+java.util.regex.Pattern.quote(code)+"(?![A-Z0-9])").matcher(stem).find();}
    @Transactional public ObjectNode importMigrationDrafts(ArrayNode entries,String actor){
        var result=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode();var createdProviders=result.putArray("createdProviders");var createdChannels=result.putArray("createdChannels");var createdVersions=result.putArray("createdVersions");int importedRows=0;
        for(var entry:entries){var value=entry.path("value");var providerCode=required((ObjectNode)value,"providerCode",64).toUpperCase(Locale.ROOT);var provider=providers.findByCodeIgnoreCase(providerCode).orElse(null);
            if(provider==null){var providerBody=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("name",value.path("providerName").asText()).put("code",providerCode).put("enabled",true);var view=addProvider(providerBody);provider=providers.findById(UUID.fromString(view.path("id").asText())).orElseThrow();createdProviders.add(provider.id.toString());}
            var channelCode=required((ObjectNode)value,"channelCode",96).toUpperCase(Locale.ROOT);var channel=channels.findByCodeIgnoreCase(channelCode).orElse(null);
            if(channel==null){var channelBody=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("providerId",provider.id.toString()).put("name",value.path("channelName").asText()).put("code",channelCode).put("type","专线").put("logisticsAttribute","普货").put("enabled",true);var view=addChannel(channelBody);channel=channels.findById(UUID.fromString(view.path("id").asText())).orElseThrow();createdChannels.add(channel.id.toString());}
            var sourceHash=value.path("sourceHash").asText();var duplicate=versions.findByChannelIdAndSourceHash(channel.id,sourceHash);if(duplicate.isPresent())continue;
            var rows=value.path("rows");if(!rows.isArray()||rows.isEmpty())throw AppException.unprocessable("物流迁移条目没有有效价格段："+value.path("fileName").asText());
            var body=tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("sourceHash",sourceHash).put("fileName",value.path("fileName").asText()).put("importedBy",actor).put("publishedBy","").put("auditNote","真实数据迁移产生的待审核草稿");
            body.set("rows",rows.deepCopy());body.set("issues",value.path("issues").deepCopy());body.set("summary",value.path("summary").deepCopy());body.put("validRows",rows.size()).put("errors",value.path("errors").asInt()).put("warnings",value.path("warnings").asInt());
            var draft=createDraft(channel.id,body);createdVersions.add(draft.path("id").asText());importedRows+=rows.size();}
        result.put("providersCreated",createdProviders.size()).put("channelsCreated",createdChannels.size()).put("versionsCreated",createdVersions.size()).put("priceRowsImported",importedRows);return result;
    }
    @Transactional public ObjectNode rollbackMigration(JsonNode execution){var removedVersions=0;var removedChannels=0;var removedProviders=0;var logistics=execution.path("logistics");
        for(var value:logistics.path("createdVersions")){try{var id=UUID.fromString(value.asText());var row=versions.findById(id).orElse(null);if(row!=null){if(!"draft".equals(row.status))throw AppException.conflict("已发布物流版本不能由迁移回滚删除");versions.delete(row);removedVersions++;}}catch(IllegalArgumentException ignored){}}
        versions.flush();for(var value:logistics.path("createdChannels")){try{var id=UUID.fromString(value.asText());if(versions.findByChannelIdOrderByVersionNumberDesc(id).isEmpty()&&channels.existsById(id)){channels.deleteById(id);removedChannels++;}}catch(IllegalArgumentException ignored){}}
        channels.flush();for(var value:logistics.path("createdProviders")){try{var id=UUID.fromString(value.asText());if(channels.countByProviderId(id)==0&&providers.existsById(id)){providers.deleteById(id);removedProviders++;}}catch(IllegalArgumentException ignored){}}
        return tools.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("versionsRemoved",removedVersions).put("channelsRemoved",removedChannels).put("providersRemoved",removedProviders);}
    private JsonNode providerView(LogisticsProviderEntity row){var body=(ObjectNode)row.payload.deepCopy();body.put("_version",row.version);return body;}
    private boolean restore(LogisticsChannelEntity row,String actor){if(row.archivedAt==null)return false;row.archivedAt=null;row.archivedBy=null;row.archiveReason=null;row.updatedAt=Instant.now();((ObjectNode)row.payload).put("archived",false).put("archivedAt","").put("archivedBy","").put("archiveReason","").put("restoredBy",actor).put("updatedAt",row.updatedAt.toString());channels.save(row);return true;}
    private JsonNode channelView(LogisticsChannelEntity row){var body=(ObjectNode)row.payload.deepCopy();body.put("currentVersionId",row.currentVersionId==null?"":row.currentVersionId.toString());body.put("archived",row.archivedAt!=null);body.put("archivedAt",row.archivedAt==null?"":row.archivedAt.toString());body.put("archivedBy",row.archivedBy==null?"":row.archivedBy);body.put("archiveReason",row.archiveReason==null?"":row.archiveReason);body.put("_version",row.version);return body;}
    private JsonNode versionView(LogisticsVersionEntity row){var body=(ObjectNode)row.payload.deepCopy();body.put("id",row.id.toString());body.put("channelId",row.channelId.toString());body.put("versionNumber",row.versionNumber);body.put("status",row.status);body.put("quoteReady",row.status.equals("published")&&datasetGuard.quoteReady(row.id));return body;}
    private static String required(ObjectNode body,String key,int max){var value=body.path(key).asText("").trim();if(value.isEmpty()||value.length()>max)throw AppException.unprocessable(key+"不能为空或过长");return value;}
    private static UUID uuid(String value,String message){try{return UUID.fromString(value);}catch(Exception e){throw AppException.unprocessable(message);}}
    public record Workspace(List<JsonNode> providers,List<JsonNode> channels,List<JsonNode> versions){}
}
